class Solution {
    long long prev = 0;
    bool hasPrev = false;
    int best = INT_MAX;
    void inorder(TreeNode* node) {
        if (!node) return;
        inorder(node->left);
        if (hasPrev) best = std::min(best, (int)((long long)node->val - prev));
        prev = node->val;
        hasPrev = true;
        inorder(node->right);
    }
public:
    int getMinimumDifference(TreeNode* root) {
        hasPrev = false; best = INT_MAX;
        inorder(root);
        return best;
    }
};
